"""A layout move lands from `next` (`queue`'s "Moves"): a PR whose body says `Move: tools/move/MAP.toml` is regenerated by the
sync on the tip below it with that tree's own `rename.py`, certified by its own `move_check.py`, and lands as that one commit
on its review; the members above it merge across it, restacked by `restack.py` when the move touches what they change.  The
scripts are the tree's own, copied into a throwaway origin with a map that moves `old_proto/` to `new_proto/`."""
from __future__ import annotations

import json
from pathlib import Path

import pytest

from test_drive_checked import _checked, _pass
from test_drive_review import Review, _main, _move_main
from test_queue import World, _git

ROOT = Path(__file__).resolve().parents[3]
SCRIPTS = ("tools/move/rename.py", "tools/move/layout.py", "tools/move/restack.py", "tools/verity/check/move_check.py")
MAP, BAD = "tools/move/demo_map.toml", "tools/move/bad_map.toml"
EXCLUDE = '[rewrite]\nexclude = ["tools/move/**", "tools/research/src/research/store/moves.json"]\n\n'
B = "import old_proto.a\n\nX = old_proto.a.f()\n"
REGISTRY = ".agents/skills/using-slack/registry.json"


@pytest.fixture
def world(tmp_path):
    w = World(tmp_path)
    _move_main(w, {**{p: (ROOT / p).read_text() for p in SCRIPTS},
                   "tools/verity/check/pins.py": "PINS = ()\n",
                   "tools/research/src/research/store/moves.json": '{"moves": []}\n',
                   MAP: EXCLUDE + '[words]\n"old_proto" = "new_proto"\n',
                   BAD: EXCLUDE + '[words]\n"banana" = "cherry"\n',
                   "old_proto/__init__.py": "", "old_proto/a.py": "def f():\n    return 1\n", "b.py": B,
                   "fruit.py": "banana = 1\n",
                   REGISTRY: json.dumps({"handles": [{"handle": f"lane-{n}", "holder": "a lane"} for n in range(1, 5)]})})
    w.gh.closed = []
    w.gh.close = lambda n, comment: w.gh.closed.append((n, comment))
    return w


def _move_pr(world: World, n: int, map: str = MAP) -> None:
    """A move PR whose head is the request: the move as its owner made it on an older `main`."""
    head = world.change({"old_proto/__init__.py": None, "old_proto/a.py": None, "new_proto/__init__.py": "",
                         "new_proto/a.py": "def f():\n    return 1\n", "b.py": B.replace("old_proto", "new_proto")})
    world.gh.put(n, head, body=f"Lane `lane-{n}`.\nMove: {map}\n")


def _show(world: World, ref: str, path: str) -> str:
    return _git(world.origin, "show", f"{ref}:{path}")


def _parents(world: World, ref: str) -> list[str]:
    return _git(world.origin, "rev-list", "--parents", "-n", "1", ref).split()[1:]


def _member(world: World, n: int) -> str:
    return next(c for c in _git(world.origin, "rev-list", "--first-parent", "refs/heads/next").split()
                if _git(world.origin, "log", "-1", "--format=%s", c).startswith(f"Queue: #{n} "))


def test_a_move_is_regenerated_on_a_moved_checked_certified_at_nexts_bottom_and_lands_as_one_commit(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    world.gh.put(1, world.change({"old_proto/c.py": "C = 1\n"}))    # lands first: the move must carry a file its head lacks
    _move_pr(world, 2)
    world.gh.put(3, world.change({"c.txt": "3\n"}))
    h.review(1)
    assert h.tick().startswith("landed #1"), world.logs
    tip = _checked(world)
    move = _member(world, 2)
    assert _parents(world, move) == [tip]                         # next's bottom member, one commit on `checked`'s tip
    body = _git(world.origin, "log", "-1", "--format=%B", move)
    assert f"Move: {MAP}" in body and f"Head: {world.gh.prs[2].head}" in body
    files = _git(world.origin, "ls-tree", "-r", "--name-only", move).split()
    assert "new_proto/c.py" in files and not [f for f in files if f.startswith("old_proto/")]
    assert _show(world, move, "b.py") == B.replace("old_proto", "new_proto").rstrip("\n")
    assert any(f"#2's move ({MAP}) regenerated on {tip[:12]} as {move[:12]}" in x for x in world.logs), world.logs
    assert _parents(world, _member(world, 3))[0] == move          # #3 doesn't touch the move: a plain merge above it

    h.review(2)
    assert h.tick().startswith("landed #2"), world.logs
    assert _checked(world) == move and world.on_next(h.q) == [3]
    assert any(p.startswith(f"@lane-2 queue: #2's move ({MAP}) landed on `checked` as {move[:12]}") for p in h.posts), h.posts
    h.tick()
    assert world.on_next(h.q) == [3]                              # still open at a head `checked` lacks: not admitted again
    st = h.q.status()
    assert st[2].state == "queued" and st[2].why.startswith("landed on `checked`"), st[2]
    _pass(h)                                                      # #1's after-landing run, then the move's
    h.tick()
    assert _main(world) == tip and world.gh.closed == []
    _pass(h)
    h.tick()
    assert _main(world) == move
    assert world.gh.closed == [(2, f"Landed in `main` at {move[:12]}: its move ({MAP}), regenerated by drive as {move[:12]}.")]
    assert any(p.startswith("@lane-2 queue: #2 landed in `main`") and "drive closed it" in p for p in h.posts), h.posts


def test_a_member_conflicting_only_with_the_move_is_restacked_onto_it(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    head = world.change({"b.py": B.replace("f()", "f() + 1"), "old_proto/d.py": "D = 1\n"})
    world.gh.put(2, head)
    h.tick()
    assert world.on_next(h.q) == [1, 2], world.logs
    two = _member(world, 2)
    first, restacked = _parents(world, two)
    assert first == _member(world, 1) and restacked != head
    assert _git(world.origin, "merge-base", "--is-ancestor", head, restacked) == ""
    assert _show(world, two, "b.py") == "import new_proto.a\n\nX = new_proto.a.f() + 1"
    assert _show(world, two, "new_proto/d.py") == "D = 1"
    assert any(f"#2 at {head[:8]} restacked through the move" in x for x in world.logs), world.logs


def test_a_member_with_a_conflict_of_its_own_above_the_move_is_refused(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    world.gh.put(2, world.change({"c.txt": "2\n"}))
    world.gh.put(3, world.change({"c.txt": "3\n", "b.py": B.replace("f()", "f() + 3")}))
    h.tick()
    assert world.on_next(h.q) == [1, 2], world.logs
    st = h.q.status()
    assert st[3].state == "refused" and "c.txt" in st[3].why and "restacked through the move" in st[3].why, st[3]


def test_a_move_move_check_refuses_is_kept_out_and_its_owner_told_why(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    world.gh.put(1, world.change({"fruit.py": "banana = 2\n"}), body=f"Lane `lane-1`.\nMove: {BAD}\n")
    world.gh.put(2, world.change({"c.txt": "2\n"}))
    h.tick()
    assert world.on_next(h.q) == [2], world.logs
    st = h.q.status()
    assert st[1].state == "refused" and "isn't certified" in st[1].why and "move_check.py" in st[1].why, st[1]
    assert any("#1" in p and "isn't certified" in p for p in h.posts), h.posts
